{
  "report": "Resumo executivo (até 2025-10-01): RECV3 apresenta perfil de continuação baixista em médio e longo prazo com consolidação lateral de curto prazo. As médias móveis (MM20, MM50 e especialmente MM200) estão orientadas para baixo e o preço se mantém abaixo da MM200 e próximo/abaixo das médias curtas, indicando pressão vendedora estrutural. O MACD está próximo de zero com histograma fraco/negativo, sinalizando momentum fraco a ligeiramente baixista; o RSI em torno de 40 confirma falta de força compradora. As Bandas de Bollinger estão relativamente contraídas recentemente e o preço transita na metade inferior da banda, apontando compressão de volatilidade e risco de um rompimento direcional. O volume vem decrescendo em comparação com os picos de maio/junho, o que reduz a convicção dos movimentos de alta recentes e indica que a atual consolidação ocorre com pouca participação compradora.",
  "signal": "Baixa",
  "support_levels": [
    12.30,
    12.80,
    13.30
  ],
  "resistance_levels": [
    13.50,
    14.50,
    15.80
  ],
  "indicator_readings": [
    {
      "indicator": "MM20",
      "reading": "≈ 13.00 (descendente)",
      "interpretation": "Média curta levemente acima/ao redor do preço e inclinada para baixo — curto-prazo com viés baixista."
    },
    {
      "indicator": "MM50",
      "reading": "≈ 13.20 (descendente)",
      "interpretation": "Média de médio prazo acima da MM20 e do preço — confirma pressão vendedora de prazo médio."
    },
    {
      "indicator": "MM200",
      "reading": "≈ 14.70 (descendente)",
      "interpretation": "Média de longo prazo ainda significativamente acima do preço — tendência de longo prazo claramente baixista."
    },
    {
      "indicator": "EMA9",
      "reading": "≈ 12.95 (próxima ao preço)",
      "interpretation": "EMA rápida acompanhando o preço, ligeiramente abaixo da EMA21 — indica fraqueza nas tentativas de recuperação de curto prazo."
    },
    {
      "indicator": "EMA21",
      "reading": "≈ 13.00",
      "interpretation": "Confirmação da zona de resistência curta; cruzamentos recentes favoreceram vendedores."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD ≈ -0.02; linha de sinal ≈ -0.01; histograma pequeno negativo",
      "interpretation": "Momentum neutro a levemente negativo — não há força compradora consistente no momento."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "Bandas estreitas; preço na metade inferior/próximo da banda inferior",
      "interpretation": "Baixa volatilidade atual (compressão). Preço na metade inferior sugere pressão vendedora e possibilidade de rompimento direcionado."
    },
    {
      "indicator": "RSI (14)",
      "reading": "≈ 40",
      "interpretation": "RSI neutro/baixista (abaixo de 50, longe de sobrevenda/compra extrema) — momentum fraco."
    },
    {
      "indicator": "Volume",
      "reading": "Volumes em queda comparados a picos anteriores (maio/junho)",
      "interpretation": "Movimentos recentes apresentam baixa participação — confirmações de tendência têm baixa convicção."
    }
  ]
}
